:root {
  --ink: #08110f;
  --deep: #0c1a17;
  --panel: rgba(11, 27, 24, 0.92);
  --panel-2: rgba(19, 42, 36, 0.9);
  --cream: #f8edcb;
  --cream-dim: #d9caa4;
  --gold: #ffce5c;
  --gold-deep: #e39b26;
  --teal: #57e2c2;
  --teal-deep: #1d8e7c;
  --coral: #ff7a5c;
  --violet: #b98cff;
  --line: rgba(255, 232, 176, 0.2);
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: #06100e;
  color: var(--cream);
  font-family: "Trebuchet MS", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

#app {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background:
    radial-gradient(120% 90% at 50% 0%, #173a32 0%, #0a1a16 55%, #050d0b 100%);
  overflow: hidden;
}

#app::before {
  content: "";
  position: absolute;
  inset: -20%;
  background:
    radial-gradient(closest-side at 20% 30%, rgba(87, 226, 194, 0.09), transparent 70%),
    radial-gradient(closest-side at 80% 70%, rgba(255, 206, 92, 0.07), transparent 70%);
  pointer-events: none;
}

#game {
  position: relative;
  display: block;
  background: #0a1a16;
  box-shadow: 0 0 0 1px rgba(255, 232, 176, 0.08), 0 30px 90px rgba(0, 0, 0, 0.65);
  border-radius: 2px;
  touch-action: none;
  z-index: 1;
}

/* ---------- shared UI ---------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: none;
  align-items: center;
  justify-content: center;
  padding: calc(18px + var(--safe-top)) calc(18px + var(--safe-right)) calc(18px + var(--safe-bottom)) calc(18px + var(--safe-left));
  overflow: hidden;
}
.screen.is-active { display: flex; animation: screenIn 0.32s cubic-bezier(.2,.8,.2,1) both; }
.screen-modal { background: radial-gradient(90% 90% at 50% 40%, rgba(4, 12, 10, 0.55), rgba(2, 7, 6, 0.88)); backdrop-filter: blur(7px); -webkit-backdrop-filter: blur(7px); }
.screen-levels, .screen-howto { background: radial-gradient(100% 100% at 50% 0%, rgba(7, 20, 17, 0.72), rgba(3, 9, 8, 0.94)); backdrop-filter: blur(9px); -webkit-backdrop-filter: blur(9px); }

@keyframes screenIn {
  from { opacity: 0; transform: scale(0.985); }
  to { opacity: 1; transform: scale(1); }
}

.eyebrow {
  font-size: 11px;
  letter-spacing: 0.28em;
  font-weight: 800;
  color: var(--teal);
  text-transform: uppercase;
  text-shadow: 0 0 18px rgba(87, 226, 194, 0.35);
}

h2 {
  margin: 6px 0 0;
  font-family: "Arial Black", "Trebuchet MS", sans-serif;
  font-size: clamp(30px, 4.4vw, 48px);
  line-height: 0.98;
  letter-spacing: -0.02em;
  color: var(--cream);
  text-shadow: 0 4px 0 rgba(0, 0, 0, 0.32), 0 14px 40px rgba(0, 0, 0, 0.5);
}

/* ---------- title ---------- */

.screen-title {
  background:
    linear-gradient(180deg, rgba(3, 10, 8, 0.34) 0%, rgba(3, 10, 8, 0.05) 38%, rgba(3, 10, 8, 0.76) 100%);
  align-items: center;
}
.screen-title::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 55% at 50% 42%, rgba(255, 206, 92, 0.12), transparent 70%);
  pointer-events: none;
}

.title-wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: min(760px, 94vw);
  padding: 12px;
  animation: floaty 7s ease-in-out infinite;
}
@keyframes floaty { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-7px); } }

.title-kicker {
  font-size: clamp(8px, 1.1vw, 12px);
  letter-spacing: 0.4em;
  font-weight: 800;
  color: var(--cream-dim);
  margin-bottom: 4px;
  text-shadow: 0 2px 12px #000;
  opacity: 0.9;
}

.logo {
  margin: 0;
  line-height: 0.78;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: rotate(-2deg);
  filter: drop-shadow(0 18px 24px rgba(0, 0, 0, 0.5));
}
.logo span { display: block; font-family: "Arial Black", "Trebuchet MS", sans-serif; }
.logo-rayman {
  font-size: clamp(52px, 10.5vw, 124px);
  letter-spacing: -0.035em;
  color: #ffd76e;
  background: linear-gradient(180deg, #fff3b4 0%, #ffce5c 36%, #f09a22 68%, #b85c10 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 3px 0 #5d2a06;
  -webkit-text-stroke: 2px rgba(48, 19, 3, 0.55);
  paint-order: stroke fill;
}
.logo-origins {
  font-size: clamp(26px, 5.2vw, 62px);
  letter-spacing: 0.24em;
  margin-left: 0.24em;
  color: #eafaf3;
  background: linear-gradient(180deg, #ffffff 0%, #d8f6e9 40%, #8ec9b8 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.45);
  -webkit-text-stroke: 1.5px rgba(5, 30, 24, 0.5);
  paint-order: stroke fill;
}
.logo-lum {
  margin-top: 12px;
  font-size: clamp(13px, 2vw, 23px);
  letter-spacing: 0.58em;
  margin-left: 0.58em;
  color: #ff8d6f;
  text-shadow: 0 0 22px rgba(255, 122, 92, 0.55), 0 3px 0 rgba(70, 10, 0, 0.4);
}
.tagline {
  margin: clamp(12px, 2.2vh, 22px) 0 clamp(14px, 2.6vh, 28px);
  font-size: clamp(12px, 1.5vw, 17px);
  line-height: 1.55;
  color: #e4f4ec;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.85), 0 1px 0 rgba(0, 0, 0, 0.6);
}

.menu { display: flex; flex-direction: column; align-items: center; gap: 9px; width: min(340px, 84vw); }

.btn {
  position: relative;
  appearance: none;
  border: 0;
  cursor: pointer;
  font-family: "Trebuchet MS", system-ui, sans-serif;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--cream);
  border-radius: 14px;
  padding: 13px 22px;
  font-size: 14px;
  transition: transform 0.12s ease, filter 0.12s ease, box-shadow 0.12s ease;
  touch-action: manipulation;
}
.btn:focus-visible { outline: 3px solid var(--teal); outline-offset: 3px; }
.btn:active { transform: translateY(2px) scale(0.985); }

.btn-primary {
  width: 100%;
  padding: 12px 20px 11px;
  color: #341b04;
  background: linear-gradient(180deg, #ffe79a 0%, #ffce5c 42%, #ee9d28 100%);
  border: 2px solid rgba(255, 246, 205, 0.75);
  box-shadow: 0 7px 0 #8f4c0d, 0 16px 30px rgba(0, 0, 0, 0.42), inset 0 2px 0 rgba(255, 255, 255, 0.7);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.45);
}
.btn-primary:hover { filter: brightness(1.06) saturate(1.05); }
.btn-primary:active { box-shadow: 0 3px 0 #8f4c0d, 0 8px 18px rgba(0, 0, 0, 0.4), inset 0 2px 0 rgba(255, 255, 255, 0.7); }
.btn-big { display: block; font-family: "Arial Black", sans-serif; font-size: clamp(22px, 2.4vw, 30px); letter-spacing: 0.06em; line-height: 1.05; }
.btn-sub { display: block; font-size: 9px; letter-spacing: 0.26em; opacity: 0.72; margin-top: 3px; }

.btn-ghost {
  width: 100%;
  background: linear-gradient(180deg, rgba(30, 62, 53, 0.9), rgba(14, 34, 29, 0.9));
  border: 1.5px solid rgba(255, 232, 176, 0.22);
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  color: #e9f4ed;
}
.btn-ghost:hover { border-color: rgba(255, 206, 92, 0.55); background: linear-gradient(180deg, rgba(40, 78, 66, 0.95), rgba(19, 44, 37, 0.95)); }
.btn-text { background: none; border: 0; box-shadow: none; color: var(--cream-dim); font-size: 11px; letter-spacing: 0.18em; padding: 8px; }
.btn-text:hover { color: var(--gold); }
.btn.small { width: auto; padding: 10px 18px; font-size: 11px; }
.btn-icon-close {
  width: 42px; height: 42px; flex: 0 0 auto; padding: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.06);
  border: 1.5px solid rgba(255, 232, 176, 0.22);
  font-size: 17px; color: var(--cream);
}

.save-note {
  min-height: 18px;
  margin-top: 12px;
  font-size: 10px;
  letter-spacing: 0.16em;
  color: rgba(233, 244, 237, 0.65);
  text-transform: uppercase;
}
.title-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: clamp(12px, 2.4vh, 26px);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: rgba(233, 244, 237, 0.46);
  text-shadow: 0 1px 6px #000;
}
.foot-sep { opacity: 0.5; }

/* ---------- panels ---------- */

.panel-wrap {
  width: min(880px, 96vw);
  max-height: 94vh;
  display: flex;
  flex-direction: column;
  padding: clamp(18px, 2.4vw, 32px);
  border-radius: 26px;
  background:
    linear-gradient(180deg, rgba(27, 55, 47, 0.96), rgba(9, 25, 21, 0.97)),
    radial-gradient(120% 80% at 10% 0%, rgba(87, 226, 194, 0.12), transparent 60%);
  border: 1.5px solid rgba(255, 232, 176, 0.2);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  overflow: hidden;
  animation: panelIn 0.36s cubic-bezier(.2,.85,.25,1) both;
}
.panel-wrap.wide { width: min(1040px, 96vw); }
@keyframes panelIn { from { opacity: 0; transform: translateY(14px) scale(0.985); } to { opacity: 1; transform: none; } }

.panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding-bottom: 14px; border-bottom: 1px solid var(--line); }
.panel-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding-top: 14px; margin-top: 14px; border-top: 1px solid var(--line);
  color: var(--cream-dim); font-size: 11px; letter-spacing: 0.08em;
}

.level-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(8px, 1.2vw, 14px);
  padding: 16px 0 2px;
  overflow-y: auto;
  scrollbar-width: thin;
}
.level-card {
  position: relative;
  appearance: none;
  text-align: left;
  cursor: pointer;
  border: 1.5px solid rgba(255, 255, 255, 0.16);
  border-radius: 18px;
  padding: 0;
  overflow: hidden;
  min-height: 220px;
  background: linear-gradient(180deg, var(--a), var(--b));
  color: #fff;
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  isolation: isolate;
}
.level-card::before {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(90% 55% at 50% 18%, rgba(255, 255, 255, 0.28), transparent 62%),
    linear-gradient(180deg, transparent 32%, rgba(4, 12, 10, 0.86) 100%);
  z-index: -1;
}
.level-card::after {
  content: "";
  position: absolute;
  left: -20%; right: -20%; bottom: -42%; height: 78%;
  border-radius: 50% 50% 0 0;
  background: var(--c, rgba(4, 16, 12, 0.55));
  z-index: -1;
}
.level-card:hover:not(.locked) { transform: translateY(-5px) scale(1.012); border-color: rgba(255, 206, 92, 0.65); box-shadow: 0 18px 36px rgba(0, 0, 0, 0.45), 0 0 0 1px rgba(255, 206, 92, 0.25); }
.level-card:active:not(.locked) { transform: translateY(-1px) scale(0.995); }
.level-card.locked { cursor: not-allowed; filter: grayscale(0.85) brightness(0.52); }
.level-card.locked::after { background: rgba(2, 8, 6, 0.62); }

.card-top { position: absolute; top: 12px; left: 12px; right: 12px; display: flex; justify-content: space-between; align-items: center; z-index: 2; }
.card-num {
  display: grid; place-items: center;
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(4, 14, 11, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.28);
  font-family: "Arial Black", sans-serif; font-size: 14px;
  backdrop-filter: blur(4px);
}
.card-lock { font-size: 15px; opacity: 0.85; filter: drop-shadow(0 2px 4px #000); }
.card-art { position: absolute; inset: 0; display: grid; place-items: center; font-size: 58px; z-index: 0; filter: drop-shadow(0 10px 18px rgba(0,0,0,0.4)); transform: translateY(-16px) scale(1.02); }
.card-body { position: relative; z-index: 2; padding: 14px; }
.card-world { font-size: 9px; letter-spacing: 0.24em; text-transform: uppercase; color: rgba(255,255,255,0.72); }
.card-name { font-family: "Arial Black", sans-serif; font-size: clamp(13px, 1.25vw, 17px); line-height: 1.08; margin: 4px 0 8px; text-shadow: 0 2px 6px #000; }
.card-stats { display: flex; align-items: center; gap: 8px; font-size: 10px; color: rgba(255,255,255,0.88); }
.card-stat { display: inline-flex; align-items: center; gap: 4px; background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.12); padding: 3px 7px; border-radius: 99px; }
.card-medal { margin-left: auto; font-size: 13px; }
.card-medal.gold { color: #ffd76e; text-shadow: 0 0 10px rgba(255, 206, 92, 0.7); }
.card-medal.silver { color: #d7e4ea; }
.card-medal.bronze { color: #e9a56a; }

/* ---------- how to ---------- */

.howto-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; padding: 16px 0 4px; overflow-y: auto; }
.howto-card { background: rgba(255, 255, 255, 0.045); border: 1px solid var(--line); border-radius: 16px; padding: 16px 18px; }
.howto-card h3 { margin: 4px 0 10px; font-family: "Arial Black", sans-serif; font-size: 17px; }
.howto-icon { font-size: 22px; }
.key-list, .touch-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 9px; font-size: 12px; color: var(--cream-dim); }
.key-list li, .touch-list li { display: flex; align-items: center; gap: 9px; }
.keys { display: inline-flex; align-items: center; gap: 3px; min-width: 104px; color: var(--cream); }
kbd {
  font-family: inherit; font-size: 10px; font-weight: 800;
  background: linear-gradient(180deg, #35584e, #1a332c);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-bottom-width: 2px; border-radius: 5px; padding: 3px 6px; color: #f1fff9;
  box-shadow: 0 1px 0 rgba(0,0,0,0.4);
}
.touch-dot { width: 10px; height: 10px; border-radius: 50%; flex: 0 0 auto; box-shadow: 0 0 10px currentColor; }
.touch-dot.left { background: #9fd8ff; color: #9fd8ff; }
.touch-dot.jump { background: var(--teal); color: var(--teal); }
.touch-dot.punch { background: var(--coral); color: var(--coral); }
.touch-dot.pause { background: var(--gold); color: var(--gold); }
.howto-tips { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; padding: 14px 2px 0; font-size: 11px; color: var(--cream-dim); line-height: 1.45; }
.howto-tips b { color: var(--cream); }

/* ---------- modal ---------- */

.modal-card {
  width: min(500px, 92vw);
  text-align: center;
  padding: clamp(22px, 3vw, 36px);
  border-radius: 26px;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(87, 226, 194, 0.14), transparent 55%),
    linear-gradient(180deg, rgba(25, 51, 44, 0.98), rgba(7, 20, 17, 0.99));
  border: 1.5px solid rgba(255, 232, 176, 0.24);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.09);
  animation: panelIn 0.34s cubic-bezier(.2,.85,.25,1) both;
}
.modal-card h2 { margin-top: 8px; }
.modal-stats { display: flex; justify-content: center; gap: 18px; flex-wrap: wrap; margin: 16px 0 4px; font-size: 11px; color: var(--cream-dim); letter-spacing: 0.06em; }
.modal-stats b { display: block; color: var(--cream); font-size: 17px; margin-top: 3px; }
.modal-actions { display: flex; flex-direction: column; gap: 9px; margin-top: 18px; }
.modal-actions.row { flex-direction: row; justify-content: center; flex-wrap: wrap; }
.modal-actions.row .btn { width: auto; min-width: 120px; }
.modal-card .btn-text { margin-top: 10px; }

.results-card { width: min(600px, 94vw); }
.medal { display: inline-flex; align-items: center; gap: 10px; margin: 14px auto 4px; padding: 7px 20px 7px 12px; border-radius: 99px; background: rgba(255, 206, 92, 0.1); border: 1px solid rgba(255, 206, 92, 0.35); }
.medal-star { font-size: 26px; color: var(--gold); text-shadow: 0 0 18px rgba(255, 206, 92, 0.8); }
.medal-name { font-family: "Arial Black", sans-serif; font-size: 15px; letter-spacing: 0.18em; color: var(--gold); }
.medal.silver { background: rgba(211, 228, 234, 0.08); border-color: rgba(211, 228, 234, 0.3); }
.medal.silver .medal-star, .medal.silver .medal-name { color: #dfeaf0; text-shadow: 0 0 14px rgba(223,234,240,0.5); }
.medal.bronze { background: rgba(233, 165, 106, 0.08); border-color: rgba(233, 165, 106, 0.3); }
.medal.bronze .medal-star, .medal.bronze .medal-name { color: #e9a56a; text-shadow: 0 0 14px rgba(233,165,106,0.5); }

.results-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 18px 0 4px; }
.result-cell { padding: 12px 8px; border-radius: 14px; background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line); }
.result-label { display: block; font-size: 9px; letter-spacing: 0.2em; color: var(--cream-dim); }
.result-value { display: block; margin-top: 5px; font-family: "Arial Black", sans-serif; font-size: clamp(16px, 2vw, 21px); color: var(--cream); }
.results-best { min-height: 18px; margin-top: 10px; font-size: 10px; letter-spacing: 0.12em; color: var(--teal); text-transform: uppercase; }

.dead-card { width: min(440px, 92vw); }
.dead-copy { color: var(--cream-dim); font-size: 13px; line-height: 1.5; }

.screen-victory {
  background: radial-gradient(80% 80% at 50% 30%, rgba(255, 206, 92, 0.16), rgba(3, 9, 8, 0.93) 60%);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.victory-wrap { text-align: center; width: min(620px, 94vw); animation: panelIn 0.5s cubic-bezier(.2,.85,.25,1) both; }
.victory-wrap h2 { font-size: clamp(36px, 5.6vw, 64px); margin: 10px 0 14px; color: #ffe79a; }
.victory-wrap p { color: var(--cream-dim); line-height: 1.6; font-size: 14px; max-width: 480px; margin: 0 auto; }
.victory-totals { display: flex; justify-content: center; gap: 22px; flex-wrap: wrap; margin: 22px 0 6px; }
.victory-totals div { font-size: 11px; letter-spacing: 0.12em; color: var(--cream-dim); }
.victory-totals b { display: block; font-family: "Arial Black", sans-serif; font-size: 26px; color: var(--gold); margin-top: 3px; }

/* ---------- system bar + touch ---------- */

.system-bar {
  position: absolute;
  top: calc(10px + var(--safe-top));
  right: calc(12px + var(--safe-right));
  z-index: 30;
  display: none;
  gap: 8px;
}
#app[data-state="playing"] .system-bar { display: flex; }
.icon-btn {
  width: 42px; height: 42px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(5, 17, 14, 0.52);
  border: 1.5px solid rgba(255, 232, 176, 0.28);
  color: var(--cream);
  cursor: pointer;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  box-shadow: 0 4px 14px rgba(0,0,0,0.3);
  touch-action: manipulation;
  transition: background 0.15s ease, transform 0.12s ease;
}
.icon-btn:hover { background: rgba(20, 46, 39, 0.8); }
.icon-btn:active { transform: scale(0.92); }
.icon-btn svg { width: 20px; height: 20px; fill: currentColor; }
.icon-btn .sound-off { display: none; }
body.muted .icon-btn .sound-off { display: block; }
body.muted .icon-btn .sound-on { display: none; }

.touch-controls {
  position: absolute;
  inset: 0;
  z-index: 25;
  display: none;
  pointer-events: none;
  padding: 0 calc(16px + var(--safe-right)) calc(14px + var(--safe-bottom)) calc(16px + var(--safe-left));
}
#app[data-state="playing"].touch-device .touch-controls { display: block; }

.joystick {
  position: absolute;
  left: calc(22px + var(--safe-left));
  bottom: calc(18px + var(--safe-bottom));
  width: clamp(112px, 15vh, 156px);
  height: clamp(112px, 15vh, 156px);
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  background: radial-gradient(circle at 50% 40%, rgba(255, 255, 255, 0.09), rgba(4, 14, 11, 0.34) 70%);
  border: 2px solid rgba(255, 255, 255, 0.17);
  box-shadow: inset 0 4px 24px rgba(0, 0, 0, 0.35), 0 6px 20px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}
.joystick-ring { position: absolute; inset: 18%; border-radius: 50%; border: 1.5px dashed rgba(255, 255, 255, 0.16); }
.joystick-stick {
  position: absolute;
  left: 50%; top: 50%;
  width: 48%; height: 48%;
  margin: -24% 0 0 -24%;
  border-radius: 50%;
  display: grid; place-items: center;
  background: radial-gradient(circle at 38% 30%, rgba(255, 255, 255, 0.32), rgba(118, 200, 178, 0.18) 42%, rgba(8, 26, 21, 0.7));
  border: 2px solid rgba(255, 255, 255, 0.38);
  color: rgba(255, 255, 255, 0.82);
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.35);
  transition: transform 0.06s linear;
}
.joystick-stick svg { width: 52%; height: 52%; opacity: 0.85; }
.joystick-label {
  position: absolute; left: 0; right: 0; bottom: -18px; text-align: center;
  font-size: 8px; letter-spacing: 0.3em; color: rgba(255, 255, 255, 0.42); font-weight: 800;
}

.action-cluster {
  position: absolute;
  right: calc(20px + var(--safe-right));
  bottom: calc(16px + var(--safe-bottom));
  display: flex;
  align-items: flex-end;
  gap: clamp(10px, 2vw, 18px);
  pointer-events: none;
}
.action-btn {
  pointer-events: auto;
  touch-action: none;
  position: relative;
  width: clamp(72px, 11.5vh, 104px);
  height: clamp(72px, 11.5vh, 104px);
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  color: #fff;
  font-family: "Trebuchet MS", sans-serif;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
  box-shadow: 0 6px 0 rgba(0, 0, 0, 0.32), 0 12px 24px rgba(0, 0, 0, 0.35), inset 0 2px 0 rgba(255, 255, 255, 0.4);
  transition: transform 0.07s ease, filter 0.07s ease;
}
.action-btn:active, .action-btn.is-down { transform: translateY(4px) scale(0.95); filter: brightness(1.14); box-shadow: 0 2px 0 rgba(0,0,0,0.3), inset 0 2px 0 rgba(255,255,255,0.35); }
.action-btn .btn-glyph { font-size: clamp(24px, 4vh, 34px); line-height: 1; }
.action-btn .btn-label { font-size: clamp(7px, 1.1vh, 10px); letter-spacing: 0.16em; opacity: 0.92; }
.action-btn.jump { background: radial-gradient(circle at 35% 28%, #a5ffe9, #37c9a9 45%, #147d69 100%); border-color: rgba(213, 255, 244, 0.75); margin-bottom: clamp(6px, 1.6vh, 16px); }
.action-btn.punch { background: radial-gradient(circle at 35% 28%, #ffc6a8, #ff7a5c 46%, #b8361d 100%); border-color: rgba(255, 216, 199, 0.75); }

.rotate-hint {
  position: absolute; inset: 0; z-index: 60;
  display: none;
  flex-direction: column; align-items: center; justify-content: center; gap: 6px;
  text-align: center; padding: 28px;
  background: radial-gradient(80% 70% at 50% 40%, rgba(18, 47, 39, 0.98), rgba(3, 10, 8, 0.99));
}
.rotate-hint.show { display: flex; }
.rotate-icon { font-size: 54px; animation: rotateWiggle 2.4s ease-in-out infinite; }
@keyframes rotateWiggle { 0%, 55%, 100% { transform: rotate(0); } 70% { transform: rotate(90deg); } 85% { transform: rotate(90deg); } }
.rotate-hint h2 { font-size: 28px; }
.rotate-hint p { max-width: 300px; color: var(--cream-dim); font-size: 13px; line-height: 1.55; margin: 6px 0 16px; }

.toast {
  position: absolute;
  left: 50%;
  bottom: calc(96px + var(--safe-bottom));
  transform: translate(-50%, 12px);
  z-index: 50;
  padding: 9px 18px;
  border-radius: 99px;
  background: rgba(5, 17, 14, 0.88);
  border: 1px solid rgba(255, 232, 176, 0.28);
  color: var(--cream);
  font-size: 11px;
  letter-spacing: 0.1em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  backdrop-filter: blur(6px);
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- responsive ---------- */

@media (max-width: 820px) {
  .level-grid { grid-template-columns: repeat(2, 1fr); }
  .level-card { min-height: 168px; }
  .card-art { font-size: 44px; transform: translateY(-10px); }
  .howto-tips { grid-template-columns: 1fr; }
  .howto-grid { grid-template-columns: 1fr; }
}

@media (max-height: 620px) {
  .title-wrap { transform: scale(0.9); animation: none; }
  .tagline { margin: 8px 0 12px; }
  .logo-lum { margin-top: 7px; }
  .title-foot { margin-top: 8px; }
  .panel-wrap { max-height: 96vh; padding: 14px 18px; }
  .level-card { min-height: 152px; }
  .howto-grid { padding-top: 10px; }
  .howto-card { padding: 10px 14px; }
  .key-list, .touch-list { gap: 5px; }
}

@media (max-height: 500px) and (orientation: landscape) {
  .title-wrap { width: min(900px, 96vw); }
  .logo-rayman { font-size: clamp(44px, 11vh, 88px); }
  .logo-origins { font-size: clamp(22px, 5.5vh, 44px); }
  .logo-lum { font-size: 11px; margin-top: 5px; }
  .tagline { display: none; }
  .title-kicker { font-size: 8px; }
  .menu { width: min(300px, 60vw); }
  .menu-main { gap: 6px; }
  .btn { padding: 9px 16px; font-size: 12px; }
  .btn-primary { padding: 8px 16px; }
  .btn-big { font-size: 21px; }
  .btn-sub { font-size: 8px; }
  .save-note { margin-top: 5px; font-size: 8px; }
  .title-foot { display: none; }
  .panel-wrap { padding: 12px 18px; }
  .panel-head { padding-bottom: 8px; }
  .panel-head h2 { font-size: 26px; }
  .level-grid { padding-top: 10px; }
  .level-card { min-height: 128px; }
  .card-art { display: none; }
  .card-body { padding: 10px; }
  .card-name { font-size: 12px; margin: 3px 0 6px; }
  .panel-foot { padding-top: 8px; margin-top: 8px; }
  .howto-card h3 { font-size: 14px; margin-bottom: 6px; }
  .key-list, .touch-list { font-size: 10px; gap: 4px; }
  .howto-tips { display: none; }
  .modal-card { padding: 16px 22px; }
  .modal-card h2 { font-size: 26px; }
  .modal-actions { margin-top: 12px; }
  .results-grid { margin: 10px 0 2px; }
  .medal { margin-top: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001s !important; transition-duration: 0.001s !important; }
}

