  },
  desert: {
    key: 'desert',
    name: 'Desert of Dijiridoos',
    skyTop: '#3a2159',
    skyMid: '#b8576c',
    skyBottom: '#ffc46b',
    sun: { x: 0.3, y: 0.36, r: 118, color: '#fff1c4', glow: 'rgba(255,196,107,0.55)' },
    cloud: ['#ffd9a8', '#f2a37c', '#c46a6d'],
    far: ['#8a4a63', '#a65a6a'],
    mid: ['#6e3a52', '#8c4a58'],
    near: ['#45243b', '#572b40'],
    fog: 'rgba(255, 176, 120, 0.14)',
    dirt: ['#b46f3a', '#d08a4c', '#8e5029'],
    grass: ['#ffd07a', '#f0a94f', '#c77d2e'],
