338:       const y = base - Math.sin(t * 4 + 0.6) * 34 - Math.sin(t * 9 + 1.4) * 12;
339:       ctx.lineTo(x, y);
340:     }
341:     ctx.lineTo(W, 720);
342:     ctx.closePath();
343:     ctx.fill();
344:     // silhouette shrubs / rocks
345:     for (let i = 0; i < 16; i++) {
346:       const x = rng() * W;
347:       this._wrap(ctx, x, (px) => {
348:         const r = 22 + rng() * 42;
349:         ctx.fillStyle = theme.near[1];
350:         ctx.beginPath();
351:         ctx.ellipse(px, base + 10 - rng() * 20, r, r * 0.5, 0, 0, TAU);
352:         ctx.fill();
353:       });
354:     }
355:     ctx.globalAlpha = 1;
356:   }
357: 
358:   _paintForeground(ctx, theme, rng) {
359:     const W = LAYER_W;
360:     ctx.globalAlpha = 0.9;
361:     const color = theme.near[0];
362:     // top corner leaves
363:     for (let side = 0; side < 2; side++) {
364:       const x = side === 0 ? 0 : W;
365:       const dir = side === 0 ? 1 : -1;
366:       for (let i = 0; i < 6; i++) {
367:         const lx = x + dir * (30 + i * 52 + rng() * 20);
368:         const ly = -10 + i * 14 + rng() * 18;
369:         const rot = dir * (0.5 + i * 0.18);
370:         ctx.save();
371:         ctx.translate(lx, ly);
372:         ctx.rotate(rot);
373:         ctx.fillStyle = color;
374:         ctx.beginPath();
375:         ctx.ellipse(0, 0, 70, 22, 0, 0, TAU);
376:         ctx.fill();
377:         ctx.strokeStyle = 'rgba(0,0,0,0.18)';
378:         ctx.lineWidth = 2;
379:         ctx.beginPath();
380:         ctx.moveTo(-60, 0);
381:         ctx.lineTo(60, 0);
382:         ctx.stroke();
383:         ctx.restore();
384:       }
385:     }
386:     // side fronds (kept at the very edges so they frame the action)
387:     for (let side = 0; side < 2; side++) {
388:       const x = side === 0 ? -30 : W + 30;
389:       const dir = side === 0 ? 1 : -1;
390:       for (let i = 0; i < 3; i++) {
391:         const ly = 560 + i * 60 + rng() * 20;
392:         ctx.save();
393:         ctx.translate(x + dir * (20 + i * 18), ly);
394:         ctx.rotate(dir * (0.3 + i * 0.25));
395:         ctx.fillStyle = color;
396:         ctx.beginPath();
397:         ctx.ellipse(0, 0, 80, 24, 0, 0, TAU);
398:         ctx.fill();
399:         ctx.restore();
400:       }
401:     }
402:     ctx.globalAlpha = 1;
403:   }
404: 
405:   _wrap(ctx, x, draw) {
406:     draw(x);
407:     if (x < 200) draw(x + LAYER_W);
408:     if (x > LAYER_W - 200) draw(x - LAYER_W);
409:   }
410: 
411:   /* ------------------------------------------------------------------ */
412:   /* Scene                                                               */
413:   /* ------------------------------------------------------------------ */
414:   draw(world, time) {
415:     const ctx = this.ctx;
416:     this.time = time;
417:     const cam = world ? world.camera : this.camera;
418:     this.camera = cam;
419:     ctx.save();
420:     this._drawSky(ctx);
421:     this._drawLayer(ctx, this.layers.clouds, 0.05, 0.03);
422:     this._drawLayer(ctx, this.layers.far, 0.14, 0.07);
423:     this._drawLayer(ctx, this.layers.mid, 0.32, 0.12);
424:     this._drawLayer(ctx, this.layers.near, 0.55, 0.2);
425:     ctx.restore();
426: 
427:     if (world) {
428:       ctx.save();
429:       const sx = cam.shakeX || 0, sy = cam.shakeY || 0;
430:       ctx.translate(-Math.round(cam.x) + sx, -Math.round(cam.y) + sy);
431:       this._drawWater(ctx, world, time);
432:       this._drawProps(ctx, world, time);
433:       this._drawTerrain(ctx, world, time);
434:       this._drawHazards(ctx, world, time);
435:       this._drawSigns(ctx, world, time);
436:       this._drawCheckpoints(ctx, world, time);
437:       this._drawSprings(ctx, world, time);
438:       this._drawPickups(ctx, world, time);
439:       this._drawEnemies(ctx, world, time);
440:       if (world.boss && !world.boss.defeated) drawBoss(ctx, world.boss, time);
441:       this._drawShockwaves(ctx, world, time);
442:       this._drawProjectiles(ctx, world, time);
443:       this._drawParticles(ctx, world, time);
444:       if (world.player) drawPlayer(ctx, world.player, time);
445:       if (world.goal) drawGoal(ctx, world.goal, time);
446:       this._drawFloatingTexts(ctx, world, time);
447:       ctx.restore();
448:       ctx.save();
449:       this._drawLayer(ctx, this.layers.fore, 1.18, 0.35);
450:       ctx.restore();
451:       this._drawAmbient(ctx, world, time);
452:       this._drawHUD(ctx, world, time);
453:       if (world.flash > 0) {
454:         ctx.fillStyle = `rgba(255, 250, 230, ${clamp(world.flash, 0, 1)})`;
455:         ctx.fillRect(0, 0, VIEW_W, VIEW_H);
456:       }
457:       if (world.fade > 0) {
458:         ctx.fillStyle = `rgba(2, 7, 6, ${clamp(world.fade, 0, 1)})`;
459:         ctx.fillRect(0, 0, VIEW_W, VIEW_H);
460:       }
461:     }
462:     ctx.drawImage(this.vignette, 0, 0);
463:   }
464: 
465:   _drawSky(ctx) {
466:     const t = this.theme;
467:     const g = ctx.createLinearGradient(0, 0, 0, VIEW_H);
468:     g.addColorStop(0, t.skyTop);
469:     g.addColorStop(0.52, t.skyMid);
470:     g.addColorStop(1, t.skyBottom);
471:     ctx.fillStyle = g;
472:     ctx.fillRect(0, 0, VIEW_W, VIEW_H);
473: 
474:     // stars for dark theme
475:     if (t.key === 'dark') {
476:       ctx.save();
477:       const rng = mulberry32(99);
478:       for (let i = 0; i < 90; i++) {
479:         const x = rng() * VIEW_W;
480:         const y = rng() * 340;
481:         const a = 0.25 + rng() * 0.65;
482:         ctx.globalAlpha = a * (0.6 + Math.sin(this.time * 2 + i) * 0.4);
483:         ctx.fillStyle = '#fff4e0';
484:         ctx.beginPath();
485:         ctx.arc(x, y, rng() * 1.4 + 0.4, 0, TAU);
486:         ctx.fill();
487:       }
488:       ctx.restore();
489:     }
490: 
491:     // sun / moon
492:     const sun = t.sun;
493:     const sx = sun.x * VIEW_W - this.camera.x * 0.02;
494:     const sy = sun.y * VIEW_H - this.camera.y * 0.02;
495:     ctx.save();
496:     ctx.globalCompositeOperation = 'lighter';
497:     const glow = ctx.createRadialGradient(sx, sy, sun.r * 0.2, sx, sy, sun.r * 3.4);
498:     glow.addColorStop(0, sun.glow);
499:     glow.addColorStop(0.4, sun.glow.replace(/[\d.]+\)$/, '0.12)'));
500:     glow.addColorStop(1, 'rgba(255,255,255,0)');
501:     ctx.fillStyle = glow;
502:     ctx.beginPath();
503:     ctx.arc(sx, sy, sun.r * 3.4, 0, TAU);
504:     ctx.fill();
505:     ctx.globalCompositeOperation = 'source-over';
506:     const disc = ctx.createRadialGradient(sx - sun.r * 0.25, sy - sun.r * 0.25, 4, sx, sy, sun.r);
507:     disc.addColorStop(0, '#fffdf0');
508:     disc.addColorStop(0.55, sun.color);
509:     disc.addColorStop(1, t.key === 'dark' ? '#ffb1c8' : '#ffd88a');
510:     ctx.fillStyle = disc;
511:     ctx.beginPath();
512:     ctx.arc(sx, sy, sun.r, 0, TAU);
513:     ctx.fill();
514:     ctx.restore();
515:   }
516: 
517:   _drawLayer(ctx, layer, factor, yFactor = 0.05) {
518:     if (!layer) return;
519:     const offset = -(((this.camera.x || 0) * factor) % LAYER_W);
520:     const y = -((this.camera.y || 0) * yFactor);
521:     ctx.drawImage(layer, offset, y);
522:     ctx.drawImage(layer, offset + LAYER_W, y);
523:     if (offset > -0.5) ctx.drawImage(layer, offset - LAYER_W, y);
524:   }
525: 
526:   /* ------------------------------------------------------------------ */
527:   /* World rendering                                                     */
528:   /* ------------------------------------------------------------------ */
529:   _drawWater(ctx, world, time) {
530:     const bodies = world.level.waterBodies || [];
531:     for (const body of bodies) {
532:       const x = body.x0 * TILE;
533:       const w = (body.x1 - body.x0 + 1) * TILE;
534:       const top = body.topRow * TILE;
535:       const bottom = world.level.worldHeight + 40;
536:       const isLava = body.type === 'lava';
537:       const deep = isLava ? '#4a0d10' : '#053c4c';
538:       const mid = isLava ? '#b62d12' : '#0b6c7c';
539:       const bright = isLava ? '#ff8a2e' : '#35c9cf';
540:       ctx.save();
541:       ctx.beginPath();
542:       ctx.rect(x, top - 4, w, bottom - top + 4);
543:       ctx.clip();
544:       const g = ctx.createLinearGradient(0, top, 0, bottom);
545:       g.addColorStop(0, bright);
546:       g.addColorStop(0.18, mid);
547:       g.addColorStop(1, deep);
548:       ctx.fillStyle = g;
549:       ctx.fillRect(x, top - 4, w, bottom - top + 4);
550: 
551:       // animated surface
552:       const surfaceY = top + Math.sin(time * 2.2 + x * 0.01) * 3;
553:       ctx.beginPath();
554:       ctx.moveTo(x, surfaceY + 6);
555:       for (let px = 0; px <= w; px += 12) {
556:         const wy = surfaceY + Math.sin(time * 2.4 + (x + px) * 0.022) * 4 + Math.sin(time * 1.1 + (x + px) * 0.008) * 3;
557:         ctx.lineTo(x + px, wy);
558:       }
559:       ctx.lineTo(x + w, bottom);
560:       ctx.lineTo(x, bottom);
561:       ctx.closePath();
562:       const sg = ctx.createLinearGradient(0, surfaceY - 8, 0, surfaceY + 46);
563:       sg.addColorStop(0, isLava ? 'rgba(255, 220, 120, 0.9)' : 'rgba(190, 255, 250, 0.8)');
564:       sg.addColorStop(0.25, isLava ? 'rgba(255, 120, 40, 0.65)' : 'rgba(70, 220, 215, 0.55)');
565:       sg.addColorStop(1, 'rgba(0,0,0,0)');
566:       ctx.fillStyle = sg;
567:       ctx.fill();
568:       // foam line
569:       ctx.strokeStyle = isLava ? 'rgba(255,220,150,0.9)' : 'rgba(210,255,250,0.85)';
570:       ctx.lineWidth = 2.5;
571:       ctx.beginPath();
572:       for (let px = 0; px <= w; px += 12) {
573:         const wy = surfaceY + Math.sin(time * 2.4 + (x + px) * 0.022) * 4 + Math.sin(time * 1.1 + (x + px) * 0.008) * 3;
574:         if (px === 0) ctx.moveTo(x + px, wy); else ctx.lineTo(x + px, wy);
575:       }
576:       ctx.stroke();
577:       // highlights / bubbles
578:       const rng = mulberry32(body.x0 * 31 + body.topRow);
579:       for (let i = 0; i < 14; i++) {
580:         const bx = x + rng() * w;
581:         const by = top + 12 + ((time * (isLava ? 40 : 24) + i * 53) % (bottom - top - 20));
582:         ctx.globalAlpha = 0.18 + (i % 4) * 0.08;
583:         ctx.fillStyle = isLava ? '#ffcf7a' : '#d6fffa';
584:         ctx.beginPath();
585:         ctx.ellipse(bx, by, 3 + (i % 3) * 2, 1.6 + (i % 2), 0, 0, TAU);
586:         ctx.fill();
587:       }
588:       ctx.globalAlpha = 1;
589:       if (isLava) {
590:         ctx.globalCompositeOperation = 'lighter';
591:         const lg = ctx.createLinearGradient(0, top, 0, top + 140);
592:         lg.addColorStop(0, 'rgba(255,110,40,0.3)');
593:         lg.addColorStop(1, 'rgba(255,60,20,0)');
594:         ctx.fillStyle = lg;
595:         ctx.fillRect(x, top - 60, w, 200);
596:       }
597:       ctx.restore();
598:     }
599:   }
600: 
601:   _drawProps(ctx, world, time) {
602:     for (const prop of world.level.props) {
603:       if (!this._visible(prop.x, prop.y, 320, 360)) continue;
604:       drawProp(ctx, prop, this.theme, time);
605:     }
606:   }
607: 
608:   _drawTerrain(ctx, world, time) {
609:     const level = world.level;
610:     const cam = world.camera;
611:     const T = TILE;
612:     const x0 = Math.max(0, Math.floor(cam.x / T) - 1);
613:     const x1 = Math.min(level.width - 1, Math.ceil((cam.x + VIEW_W) / T) + 1);
614:     const y0 = Math.max(0, Math.floor(cam.y / T) - 1);
615:     const y1 = Math.min(level.rows - 1, Math.ceil((cam.y + VIEW_H) / T) + 1);
616:     const t = this.theme;
617: 
618:     for (let ty = y0; ty <= y1; ty++) {
619:       for (let tx = x0; tx <= x1; tx++) {
620:         if (!this._solid(level, tx, ty)) continue;
621:         const x = tx * T, y = ty * T;
622:         const hash = (tx * 73856093 ^ ty * 19349663) >>> 0;
623:         const shade = (hash % 3);
624:         const above = this._solid(level, tx, ty - 1);
625:         const left = this._solid(level, tx - 1, ty);
626:         const right = this._solid(level, tx + 1, ty);
627:         const below = this._solid(level, tx, ty + 1);
628: 
629:         // dirt body
630:         ctx.fillStyle = t.dirt[shade];
631:         ctx.fillRect(x - 0.5, y - 0.5, T + 1, T + 1);
632:         if (shade === 1) {
633:           ctx.fillStyle = 'rgba(255,255,255,0.03)';
634:           ctx.fillRect(x + 4, y + 6, T - 8, T - 12);
635:         }
636:         // pebbles
637:         if (hash % 11 === 0) {
638:           ctx.fillStyle = 'rgba(0,0,0,0.18)';
639:           ctx.beginPath();
640:           ctx.ellipse(x + 12 + (hash % 20), y + 18 + (hash % 16), 5, 3, 0.4, 0, TAU);
641:           ctx.fill();
642:         }
643:         if (hash % 17 === 0) {
644:           ctx.strokeStyle = 'rgba(255,255,255,0.09)';
645:           ctx.lineWidth = 2;
646:           ctx.beginPath();
647:           ctx.moveTo(x + 8, y + 20);
648:           ctx.quadraticCurveTo(x + 20, y + 34, x + 16, y + 46);
649:           ctx.stroke();
650:         }
651: 
652:         // grass top
653:         if (!above) {
654:           const g = ctx.createLinearGradient(0, y - 3, 0, y + 16);
655:           g.addColorStop(0, t.grass[0]);
656:           g.addColorStop(0.55, t.grass[1]);
657:           g.addColorStop(1, t.grass[2]);
658:           ctx.fillStyle = g;
659:           ctx.beginPath();
660:           ctx.moveTo(x - 1, y + 14);
661:           ctx.lineTo(x - 1, y + 3);
662:           ctx.quadraticCurveTo(x + T * 0.5, y - 5, x + T + 1, y + 3);
663:           ctx.lineTo(x + T + 1, y + 14);
664:           ctx.closePath();
665:           ctx.fill();
666:           // bright lip
667:           ctx.fillStyle = 'rgba(255,255,255,0.28)';
668:           ctx.beginPath();
669:           ctx.ellipse(x + T / 2, y + 3, T * 0.42, 3, 0, 0, TAU);
670:           ctx.fill();
671:           // blades
672:           ctx.strokeStyle = t.grass[0];
673:           ctx.lineWidth = 2;
674:           const rng = mulberry32(hash);
675:           const blades = 2 + (hash % 3);
676:           for (let i = 0; i < blades; i++) {
677:             const bx = x + 8 + rng() * (T - 16);
678:             const bh = 5 + rng() * 10;
679:             ctx.beginPath();
680:             ctx.moveTo(bx, y + 2);
681:             ctx.quadraticCurveTo(bx + 2, y - bh * 0.6, bx + (rng() - 0.5) * 7, y - bh);
682:             ctx.stroke();
683:           }
684:           // flowers / pebbles on top
685:           if (hash % 9 === 0) {
686:             const fx = x + 12 + (hash % 22);
687:             const fc = t.flower[hash % t.flower.length];
688:             ctx.fillStyle = fc;
689:             for (let k = 0; k < 5; k++) {
690:               const a = (k / 5) * TAU;
691:               ctx.beginPath();
692:               ctx.ellipse(fx + Math.cos(a) * 4, y - 2 + Math.sin(a) * 4, 2.6, 1.7, a, 0, TAU);
693:               ctx.fill();
694:             }
695:             ctx.fillStyle = '#ffe7a3';
696:             ctx.beginPath(); ctx.arc(fx, y - 2, 1.8, 0, TAU); ctx.fill();
697:           }
698:         }
699: 
700:         // exposed side shading
701:         if (!left) {
702:           ctx.fillStyle = 'rgba(0,0,0,0.18)';
703:           ctx.fillRect(x, y + 12, 5, T - 12);
704:         }
705:         if (!right) {
706:           ctx.fillStyle = 'rgba(0,0,0,0.22)';
707:           ctx.fillRect(x + T - 5, y + 12, 5, T - 12);
708:         }
709:         if (!below) {
710:           ctx.fillStyle = 'rgba(0,0,0,0.28)';
711:           ctx.beginPath();
712:           ctx.ellipse(x + T / 2, y + T, T * 0.48, 6, 0, 0, Math.PI);
713:           ctx.fill();
714:           // hanging roots
715:           if (hash % 5 === 0) {
716:             ctx.strokeStyle = t.dirt[2];
717:             ctx.lineWidth = 2;
718:             ctx.beginPath();
719:             ctx.moveTo(x + T / 2, y + T);
720:             ctx.quadraticCurveTo(x + T / 2 + 4, y + T + 10, x + T / 2 + 1, y + T + 18 + (hash % 8));
721:             ctx.stroke();
722:           }
723:         }
724:         // vines from grass edges
725:         if (!above && (!left || !right) && hash % 4 === 0) {
726:           const vx = !left ? x + 4 : x + T - 4;
727:           ctx.strokeStyle = t.grass[2];
728:           ctx.lineWidth = 2.2;
729:           ctx.beginPath();
730:           ctx.moveTo(vx, y + 8);
731:           ctx.bezierCurveTo(vx - 6, y + 24, vx + 7, y + 40, vx - 2, y + 58 + (hash % 20));
732:           ctx.stroke();
733:           ctx.fillStyle = t.grass[1];
734:           for (let i = 0; i < 3; i++) {
735:             ctx.beginPath();
736:             ctx.ellipse(vx + (i % 2 ? 4 : -4), y + 22 + i * 12, 5, 2.4, i % 2 ? 0.5 : -0.5, 0, TAU);
737:             ctx.fill();
738:           }
739:         }
740:       }
741:     }
742:   }
743: 
744:   _drawHazards(ctx, world, time) {
745:     const level = world.level;
746:     const cam = world.camera;
747:     const x0 = Math.max(0, Math.floor(cam.x / TILE) - 1);
748:     const x1 = Math.min(level.width - 1, Math.ceil((cam.x + VIEW_W) / TILE) + 1);
749:     const y0 = Math.max(0, Math.floor(cam.y / TILE) - 1);
750:     const y1 = Math.min(level.rows - 1, Math.ceil((cam.y + VIEW_H) / TILE) + 1);
751:     for (let ty = y0; ty <= y1; ty++) {
752:       for (let tx = x0; tx <= x1; tx++) {
753:         const h = level.hazards[ty * level.width + tx];
754:         if (h !== 2) continue;
755:         const x = tx * TILE, y = ty * TILE;
756:         // spikes
757:         ctx.save();
758:         const base = y + TILE;
759:         const spikes = 3;
760:         for (let i = 0; i < spikes; i++) {
761:           const sx = x + (i + 0.5) * (TILE / spikes);
762:           const sw = TILE / spikes * 0.38;
763:           const g = ctx.createLinearGradient(sx, base, sx, base - 34);
764:           g.addColorStop(0, '#5b5f6e');
765:           g.addColorStop(0.6, '#c3ccda');
766:           g.addColorStop(1, '#fff6dd');
767:           ctx.fillStyle = g;
768:           ctx.beginPath();
769:           ctx.moveTo(sx - sw, base);
770:           ctx.lineTo(sx, base - 34);
771:           ctx.lineTo(sx + sw, base);
772:           ctx.closePath();
773:           ctx.fill();
774:           ctx.strokeStyle = 'rgba(30,20,30,0.55)';
775:           ctx.lineWidth = 1.5;
776:           ctx.stroke();
777:         }
778:         ctx.fillStyle = 'rgba(0,0,0,0.22)';
779:         ctx.fillRect(x, base - 4, TILE, 4);
780:         ctx.restore();
781:       }
782:     }
783:   }
784: 
785:   _drawSigns(ctx, world, time) {
786:     for (const s of world.level.signs) {
787:       if (!this._visible(s.x, s.y, 160, 200)) continue;
788:       drawSign(ctx, s);
789:     }
790:   }
791: 
792:   _drawCheckpoints(ctx, world, time) {
793:     for (const c of world.level.checkpoints) {
794:       if (!this._visible(c.x, c.y, 160, 220)) continue;
795:       drawCheckpoint(ctx, c, this.theme, time);
796:     }
797:   }
798: 
799:   _drawSprings(ctx, world, time) {
800:     for (const s of world.level.springs) {
801:       if (!this._visible(s.x, s.y, 120, 140)) continue;
802:       drawSpring(ctx, s, this.theme, time);
