806:   _drawPickups(ctx, world, time) {
807:     for (const l of world.level.lums) {
808:       if (l.taken) continue;
809:       if (!this._visible(l.x, l.y, 60, 60)) continue;
810:       drawLum(ctx, l, time);
811:     }
812:     for (const h of world.level.hearts) {
813:       if (h.taken) continue;
814:       if (!this._visible(h.x, h.y, 70, 70)) continue;
815:       drawHeart(ctx, h, time);
816:     }
817:     for (const c of world.level.cages) {
818:       if (c.freed) continue;
819:       if (!this._visible(c.x, c.y, 120, 140)) continue;
820:       drawCage(ctx, c, time);
821:     }
822:   }
