824:   _drawEnemies(ctx, world, time) {
825:     for (const e of world.enemies) {
826:       if (!e.alive && e.deathTimer <= 0) continue;
827:       if (!this._visible(e.x, e.y, 140, 160)) continue;
828:       drawEnemy(ctx, e, time);
829:     }
830:   }
831: 
832:   _drawShockwaves(ctx, world, time) {
