531:     this.canvas.style.width = `${Math.floor(VIEW_W * scale)}px`;
532:     this.canvas.style.height = `${Math.floor(VIEW_H * scale)}px`;
533:     this.updateRotateHint();
534:   }
535: 
536:   updateRotateHint() {
537:     const portrait = window.innerHeight > window.innerWidth * 1.05;
538:     if (!portrait) this.rotateDismissed = false;
539:     const show = this.input.touchDevice && portrait && !this.rotateDismissed && this.state === 'playing';
540:     this.rotateBlocking = show;
541:     this.el.rotate.classList.toggle('show', show);
542:   }
543: 
544:   async tryLockOrientation() {
545:     if (!this.input.touchDevice) return;
546:     try {
547:       if (screen.orientation?.lock) {
548:         await screen.orientation.lock('landscape');
549:       }
550:     } catch {
551:       /* Orientation lock needs fullscreen on most browsers; ignore. */
552:     }
553:   }
554: 
555:   toast(text, duration = 1600) {
556:     if (!this.el.toast) return;
557:     this.el.toast.textContent = text;
558:     this.el.toast.classList.add('show');
559:     clearTimeout(this.toastTimer);
560:     this.toastTimer = setTimeout(() => this.el.toast.classList.remove('show'), duration);
561:   }
562: }
