564: function computeMedal(lums, total, cages, totalCages) {
565:   const ratio = total > 0 ? lums / total : 1;
566:   if (cages >= totalCages && ratio >= 0.85) return 'gold';
567:   if (ratio >= 0.6 || cages >= totalCages) return 'silver';
568:   return 'bronze';
569: }
